-- Only nonclinical metadata survives report/payload retention. No FK to clinical copies.
create table clinical_audit.hospital_operational_event (
 id uuid primary key, organization_id uuid not null,report_id uuid not null,
 integration text not null check(integration in ('eps','cos')),verification text not null check(verification in ('simulator','unverified','eps')),source_id uuid not null,
 snapshot_id uuid not null,amendment_sequence integer not null,synthetic boolean not null,
 configuration_revision bigint not null,mapping_id text not null,mapping_revision integer not null,
 mapping_sha256 text not null check(mapping_sha256 ~ '^[0-9a-f]{64}$'),
 payload_sha256 text check(payload_sha256 ~ '^[0-9a-f]{64}$'),
 actor_id uuid,worker_id uuid,action text not null,state text not null,
 attempt_id uuid,command_id uuid, finding text check(finding in ('outage','outcomeUnknown','inFlight','contactStored','reconciledNotStored','reconciliationUnresolved','reconciliationUnsupported')),remote_pass boolean,remote_errors integer,proof_outcome text check(proof_outcome in ('stored','not-stored','unresolved','unsupported')),proof_fenced boolean,
 receipt_id uuid,occurred_at timestamptz not null,
 check(actor_id is null or worker_id is null)
);
create index hospital_operational_scope on clinical_audit.hospital_operational_event(organization_id,occurred_at desc,id);
create index hospital_operational_report on clinical_audit.hospital_operational_event(report_id);
create trigger hospital_operational_immutable before update or delete or truncate on clinical_audit.hospital_operational_event for each statement execute function clinical_audit.reject_patient_access_change();
alter table clinical_audit.hospital_operational_event enable row level security;
create policy hospital_operational_append on clinical_audit.hospital_operational_event for insert to open_triage_api_runtime with check(true);
create policy hospital_operational_audit on clinical_audit.hospital_operational_event for select to open_triage_api_runtime using(organization_id=nullif(current_setting('open_triage.audit_organization_id',true),'')::uuid);
revoke all on clinical_audit.hospital_operational_event from public,open_triage_api_runtime;
grant select,insert on clinical_audit.hospital_operational_event to open_triage_api_runtime;
-- Invoker function runs under the ordinary trusted API writer. No new elevated role.
create function clinical_audit.record_hospital_operational_event() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if tg_table_name='cos_delivery_event' then
  insert into clinical_audit.hospital_operational_event(id,organization_id,report_id,integration,verification,source_id,snapshot_id,amendment_sequence,synthetic,configuration_revision,mapping_id,mapping_revision,mapping_sha256,payload_sha256,actor_id,worker_id,action,state,receipt_id,attempt_id,command_id,finding,proof_outcome,proof_fenced,occurred_at)
   select new.id,d.organization_id,d.report_id,'cos',case when (select v.settings->>'mode' from app_identity.hospital_cos_version v where v.group_id=d.group_id and v.revision=d.configuration_revision)='simulator' then 'simulator' else 'unverified' end,d.id,d.snapshot_id,d.amendment_sequence,r.synthetic,d.configuration_revision,d.mapping_id,d.mapping_revision,d.mapping_sha256,p.payload_sha256,new.actor_id,new.worker_id,case when new.evidence->>'action'='reconcile' then 'cos.reconcile' when c.automatic_ordinal is not null then 'cos.automatic-retry' when c.id is not null then 'cos.manual-retry' else 'cos.delivery' end,new.state,
    case when new.evidence->>'receiptId' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (new.evidence->>'receiptId')::uuid end,new.attempt_id,case when new.evidence->>'action'='reconcile' and new.evidence->>'commandId' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (new.evidence->>'commandId')::uuid else a.recovery_command_id end,case when new.finding in ('outage','outcomeUnknown','inFlight','contactStored','reconciledNotStored','reconciliationUnresolved','reconciliationUnsupported') then new.finding end,case when new.evidence->>'outcome' in ('stored','not-stored','unresolved','unsupported') then new.evidence->>'outcome' end,case when jsonb_typeof(new.evidence->'fenced')='boolean' then (new.evidence->>'fenced')::boolean end,new.created_at
   from clinical.cos_delivery d join clinical.report r on r.id=d.report_id left join clinical.cos_payload p on p.delivery_id=d.id left join clinical.cos_attempt a on a.id=new.attempt_id left join clinical.cos_recovery_command c on c.id=a.recovery_command_id where d.id=new.delivery_id;
 elsif tg_table_name='eps_submission_attempt' then
  insert into clinical_audit.hospital_operational_event(id,organization_id,report_id,integration,verification,source_id,snapshot_id,amendment_sequence,synthetic,configuration_revision,mapping_id,mapping_revision,mapping_sha256,payload_sha256,actor_id,action,state,occurred_at)
   select new.id,s.organization_id,s.report_id,'eps','eps',s.id,s.snapshot_id,s.amendment_sequence,r.synthetic,s.configuration_revision,s.mapping_id,s.mapping_revision,s.mapping_sha256,s.payload_sha256,new.actor_id,'eps.submit','unknown',new.created_at from clinical.eps_submission s join clinical.report r on r.id=s.report_id where s.id=new.submission_id;
 else
  insert into clinical_audit.hospital_operational_event(id,organization_id,report_id,integration,verification,source_id,snapshot_id,amendment_sequence,synthetic,configuration_revision,mapping_id,mapping_revision,mapping_sha256,payload_sha256,actor_id,action,state,attempt_id,command_id,remote_pass,remote_errors,occurred_at)
   select gen_random_uuid(),s.organization_id,s.report_id,'eps','eps',s.id,s.snapshot_id,s.amendment_sequence,r.synthetic,s.configuration_revision,s.mapping_id,s.mapping_revision,s.mapping_sha256,s.payload_sha256,a.actor_id,'eps.result',new.state,a.id,a.command_id,case when new.evidence->'headers'->>'x-pass' in ('true','false') then (new.evidence->'headers'->>'x-pass')::boolean end,case when new.evidence->'headers'->>'x-errors' ~ '^\d{1,6}$' then (new.evidence->'headers'->>'x-errors')::integer end,new.created_at from clinical.eps_submission_attempt a join clinical.eps_submission s on s.id=a.submission_id join clinical.report r on r.id=s.report_id where a.id=new.attempt_id;
 end if;
 return new;
end $$;
revoke all on function clinical_audit.record_hospital_operational_event() from public;
grant execute on function clinical_audit.record_hospital_operational_event() to open_triage_api_runtime;
create trigger cos_operational_audit after insert on clinical.cos_delivery_event for each row execute function clinical_audit.record_hospital_operational_event();
create trigger eps_attempt_operational_audit after insert on clinical.eps_submission_attempt for each row execute function clinical_audit.record_hospital_operational_event();
create trigger eps_result_operational_audit after insert on clinical.eps_submission_result for each row execute function clinical_audit.record_hospital_operational_event();
-- Existing evidence is retained without copying any payload or patient value.
insert into clinical_audit.hospital_operational_event(id,organization_id,report_id,integration,verification,source_id,snapshot_id,amendment_sequence,synthetic,configuration_revision,mapping_id,mapping_revision,mapping_sha256,payload_sha256,actor_id,worker_id,action,state,receipt_id,attempt_id,command_id,finding,proof_outcome,proof_fenced,occurred_at)
 select e.id,d.organization_id,d.report_id,'cos',case when (select v.settings->>'mode' from app_identity.hospital_cos_version v where v.group_id=d.group_id and v.revision=d.configuration_revision)='simulator' then 'simulator' else 'unverified' end,d.id,d.snapshot_id,d.amendment_sequence,r.synthetic,d.configuration_revision,d.mapping_id,d.mapping_revision,d.mapping_sha256,p.payload_sha256,e.actor_id,e.worker_id,case when e.evidence->>'action'='reconcile' then 'cos.reconcile' when c.automatic_ordinal is not null then 'cos.automatic-retry' when c.id is not null then 'cos.manual-retry' else 'cos.delivery' end,e.state,case when e.evidence->>'receiptId' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (e.evidence->>'receiptId')::uuid end,e.attempt_id,case when e.evidence->>'action'='reconcile' and e.evidence->>'commandId' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (e.evidence->>'commandId')::uuid else a.recovery_command_id end,case when e.finding in ('outage','outcomeUnknown','inFlight','contactStored','reconciledNotStored','reconciliationUnresolved','reconciliationUnsupported') then e.finding end,case when e.evidence->>'outcome' in ('stored','not-stored','unresolved','unsupported') then e.evidence->>'outcome' end,case when jsonb_typeof(e.evidence->'fenced')='boolean' then (e.evidence->>'fenced')::boolean end,e.created_at from clinical.cos_delivery_event e join clinical.cos_delivery d on d.id=e.delivery_id join clinical.report r on r.id=d.report_id left join clinical.cos_payload p on p.delivery_id=d.id left join clinical.cos_attempt a on a.id=e.attempt_id left join clinical.cos_recovery_command c on c.id=a.recovery_command_id;
insert into clinical_audit.hospital_operational_event(id,organization_id,report_id,integration,verification,source_id,snapshot_id,amendment_sequence,synthetic,configuration_revision,mapping_id,mapping_revision,mapping_sha256,payload_sha256,actor_id,action,state,occurred_at)
 select a.id,s.organization_id,s.report_id,'eps','eps',s.id,s.snapshot_id,s.amendment_sequence,r.synthetic,s.configuration_revision,s.mapping_id,s.mapping_revision,s.mapping_sha256,s.payload_sha256,a.actor_id,'eps.submit','unknown',a.created_at from clinical.eps_submission_attempt a join clinical.eps_submission s on s.id=a.submission_id join clinical.report r on r.id=s.report_id;
insert into clinical_audit.hospital_operational_event(id,organization_id,report_id,integration,verification,source_id,snapshot_id,amendment_sequence,synthetic,configuration_revision,mapping_id,mapping_revision,mapping_sha256,payload_sha256,actor_id,action,state,attempt_id,command_id,remote_pass,remote_errors,occurred_at)
 select gen_random_uuid(),s.organization_id,s.report_id,'eps','eps',s.id,s.snapshot_id,s.amendment_sequence,r.synthetic,s.configuration_revision,s.mapping_id,s.mapping_revision,s.mapping_sha256,s.payload_sha256,a.actor_id,'eps.result',result.state,a.id,a.command_id,case when result.evidence->'headers'->>'x-pass' in ('true','false') then (result.evidence->'headers'->>'x-pass')::boolean end,case when result.evidence->'headers'->>'x-errors' ~ '^\d{1,6}$' then (result.evidence->'headers'->>'x-errors')::integer end,result.created_at from clinical.eps_submission_result result join clinical.eps_submission_attempt a on a.id=result.attempt_id join clinical.eps_submission s on s.id=a.submission_id join clinical.report r on r.id=s.report_id;
do $$ declare role_name text;begin foreach role_name in array array['anon','authenticated'] loop if exists(select 1 from pg_roles where rolname=role_name) then execute format('revoke all on clinical_audit.hospital_operational_event from %I',role_name);end if;end loop;end $$;
comment on table clinical_audit.hospital_operational_event is 'Append-only metadata audit; no clinical source, patient identifiers, provider bodies, endpoints or credentials. Clinical artifacts expire independently.';
